const { refreshManagedSubscriptions } = require('./managed-native-bridge')

// One bounded monitor for already-bound catalog IDs, not network discovery.
function createCatalogRecovery ({ listDevices, flowAccess, onError = () => {}, intervalMs = 2000 }) {
  const panels = new Map(), states = new Map(), pending = new Map()
  let timer = null, busy = false, generation = 0, delay = intervalMs
  const schedule = () => {
    if (!panels.size || timer) return
    timer = setTimeout(() => { timer = null; void scan() }, delay)
    timer.unref?.()
  }
  async function scan () {
    if (!panels.size || busy || !flowAccess) return
    busy = true
    try {
      const devices = await listDevices()
      const online = new Set(devices.filter(device => device.online).map(device => device.id))
      const bound = new Set([...panels.values()].flatMap(panel => panel.devices))
      for (const device of bound) {
        const current = online.has(device), previous = states.get(device)
        // An empty catalog while the controller is starting is not evidence
        // that an already-observed program was deleted.
        if (!current && previous === undefined) continue
        states.set(device, current)
        if (!current && previous !== false) {
          for (const panel of panels.values()) if (panel.devices.includes(device)) panel.unavailable(device)
        }
        if (current && previous === false) {
          pending.set(device, `catalog-${++generation}`)
        }
      }
      if (pending.size && panels.size) {
        const snapshot = await flowAccess.getSnapshot()
        let flows = snapshot.flows, changed = false
        for (const [device, epoch] of pending) for (const [panelId, panel] of panels) {
          if (!panel.devices.includes(device)) continue
          const next = refreshManagedSubscriptions(flows, { panelId, device, epoch })
          if (next) { flows = next; changed = true }
        }
        if (changed && panels.size) await flowAccess.setSnapshot({ rev: snapshot.rev, flows })
        for (const device of pending.keys()) for (const panel of panels.values()) {
          if (panel.devices.includes(device)) panel.refresh()
        }
        pending.clear()
      }
      for (const device of states.keys()) if (!bound.has(device)) states.delete(device)
      delay = intervalMs
    } catch (error) {
      delay = Math.min(Math.max(intervalMs, delay * 2), 30000)
      onError(error)
    } finally { busy = false; schedule() }
  }
  return {
    attach (panelId, devices, refresh, unavailable = () => {}) {
      const panel = { devices: [...new Set(devices)], refresh, unavailable }
      panels.set(panelId, panel); schedule()
      return () => {
        if (panels.get(panelId) === panel) panels.delete(panelId)
        if (!panels.size) { clearTimeout(timer); timer = null; pending.clear(); states.clear() }
      }
    },
    scan,
    stats: () => ({ panels: panels.size, pending: pending.size, busy })
  }
}

module.exports = { createCatalogRecovery }
